1	// credit 是本地课程学分与免修的命令行程序。
2	//
3	// 用法：credit -f 记录文件 <子命令> [参数...]
4	//
5	// 学生与课程：
6	//
7	//	student <编号>                              登记学生（编号唯一）
8	//	course <编号> <名称...> <正整数学分>          登记课程（初始开放）
9	//	course-close <编号>                          停开课程
10	//	course-open <编号>                           恢复开放课程
11	//	list-courses                                列出全部课程及状态
12	//
13	// 课程要求（编号在学生名下唯一）：
14	//
15	//	req <学生> <要求编号> <课程编号>              为学生登记课程要求
16	//
17	// 修读（编号在学生名下唯一）：
18	//
19	//	enroll <学生> <要求编号> <学期> <修读编号>    选课登记
20	//	pass   <学生> <修读编号>                      提交“通过”
21	//	fail   <学生> <修读编号>                      提交“未通过”
22	//
23	// 免修（编号在学生名下唯一）：
24	//
25	//	waiver        <学生> <要求编号> <免修编号> <依据...>  提交免修申请
26	//	revoke-waiver <学生> <免修编号> [原因...]            撤销有效免修
27	//
28	// 核对与查询：
29	//
30	//	check <学生>                                 按学生核对学分
31	//	show  <学生>                                 查看学生的要求、修读与免修历史
32	//
33	// 记录文件不存在时从空记录开始；文件无法读取或内容损坏时立即报错，
34	// 不会把它当作空记录覆盖。
35	package main
36	
37	import (
38		"bytes"
39		"errors"
40		"flag"
41		"fmt"
42		"io"
43		"os"
44		"strconv"
45		"strings"
46	
47		"github.com/descikazuyq/credit-record/credit"
48	)
49	
50	// 退出码：0 成功；1 业务规则被拒绝；2 记录文件错误。
51	const (
52		exitOK       = 0
53		exitRejected = 1
54		exitFile     = 2
55	)
56	
57	func main() {
58		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
59	}
60	
61	func run(args []string, stdout, stderr io.Writer) int {
62		fs := flag.NewFlagSet("credit", flag.ContinueOnError)
63		fs.SetOutput(stderr)
64		fs.Usage = func() {
65			fmt.Fprintln(stderr, "用法：credit -f 记录文件 <子命令> [参数...]")
66			fmt.Fprintln(stderr, "子命令：student course course-close course-open list-courses")
67			fmt.Fprintln(stderr, "        req enroll pass fail waiver revoke-waiver check show")
68			fmt.Fprintln(stderr, "详情见 credit -h")
69		}
70		file := fs.String("f", "", "记录文件路径（必需）")
71		if err := fs.Parse(args); err != nil {
72			return exitRejected
73		}
74		if strings.TrimSpace(*file) == "" {
75			fmt.Fprintln(stderr, "错误：必须用 -f 指定记录文件")
76			fs.Usage()
77			return exitRejected
78		}
79		rest := fs.Args()
80		if len(rest) == 0 {
81			fmt.Fprintln(stderr, "错误：缺少子命令")
82			fs.Usage()
83			return exitRejected
84		}
85	
86		store, existed, err := credit.Load(*file)
87		if err != nil {
88			fmt.Fprintf(stderr, "错误：%v\n", err)
89			return exitFile
90		}
91	
92		cmd, cmdArgs := rest[0], rest[1:]
93	
94		// 业务结果先写入缓冲区，只有本次变更真正落盘后才允许出现在标准输出：
95		// 保存失败时绝不能把尚未写入文件的登记、更新、提交、撤销说成已经完成。
96		// 只读命令、幂等重复等不产生变更的操作不会保存，其结果照常输出。
97		var biz bytes.Buffer
98		code, err := dispatch(store, cmd, cmdArgs, &biz)
99		if err != nil {
100			fmt.Fprintf(stderr, "错误：%v\n", err)
101		}
102	
103		// 只有真正发生变更才落盘：只读核对、纯幂等重复、被拒绝而未写入数据的
104		// 请求都不改动文件，也不会为一次查询凭空创建空文件。被拒绝的免修申请
105		// 已写入免修历史（store 标记为已变更），仍会保存。损坏文件在 Load 阶段
106		// 就已返回，绝不会走到这里覆盖原文件。
107		if store.Dirty() {
108			if saveErr := store.Save(*file); saveErr != nil {
109				// 保存没有完成：丢弃全部业务输出，只在标准错误点名保存失败与
110				// 目标记录文件，按文件错误退出码 2 结束，退出码优先级高于
111				// 业务拒绝（例如历史都没存上的被拒绝免修）。
112				fmt.Fprintf(stderr, "错误：保存记录文件 %s 失败：%v\n", *file, saveErr)
113				return exitFile
114			}
115			// 首次创建记录文件的说明放在业务结果之后；保存失败时不会出现，
116			// 也不会谎称已经创建。
117			fmt.Fprint(stdout, biz.String())
118			if !existed {
119				fmt.Fprintf(stdout, "（记录文件 %s 不存在，已从空记录开始并创建）\n", *file)
120			}
121			return code
122		}
123		fmt.Fprint(stdout, biz.String())
124		return code
125	}
126	
127	func dispatch(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
128		switch cmd {
129		case "student":
130			return cmdStudent(s, args, out)
131		case "course":
132			return cmdCourse(s, args, out)
133		case "course-close", "course-open":
134			return cmdCourseToggle(s, cmd, args, out)
135		case "list-courses":
136			return cmdListCourses(s, out)
137		case "req":
138			return cmdReq(s, args, out)
139		case "enroll":
140			return cmdEnroll(s, args, out)
141		case "pass", "fail":
142			return cmdResult(s, cmd, args, out)
143		case "waiver":
144			return cmdWaiver(s, args, out)
145		case "revoke-waiver":
146			return cmdRevoke(s, args, out)
147		case "check":
148			return cmdCheck(s, args, out)
149		case "show":
150			return cmdShow(s, args, out)
151		default:
152			return exitRejected, fmt.Errorf("未知子命令 %q", cmd)
153		}
154	}
155	
156	func cmdStudent(s *credit.Store, args []string, out io.Writer) (int, error) {
157		if len(args) != 1 {
158			return exitRejected, errors.New("用法：student <编号>")
159		}
160		st, action, err := s.AddStudent(args[0])
161		if err != nil {
162			return exitRejected, err
163		}
164		if action == credit.ActionCreated {
165			fmt.Fprintf(out, "已登记学生 %s\n", st.ID)
166		} else {
167			fmt.Fprintf(out, "学生 %s 已存在，返回原记录\n", st.ID)
168		}
169		return exitOK, nil
170	}
171	
172	func cmdCourse(s *credit.Store, args []string, out io.Writer) (int, error) {
173		if len(args) < 3 {
174			return exitRejected, errors.New("用法：course <编号> <名称...> <正整数学分>")
175		}
176		id := args[0]
177		creditN, err := strconv.Atoi(strings.TrimSpace(args[len(args)-1]))
178		if err != nil {
179			return exitRejected, fmt.Errorf("学分必须是正整数：%q", args[len(args)-1])
180		}
181		name := strings.Join(args[1:len(args)-1], " ")
182		c, action, err := s.AddCourse(id, name, creditN)
183		if err != nil {
184			return exitRejected, err
185		}
186		switch action {
187		case credit.ActionCreated:
188			fmt.Fprintf(out, "已登记课程 %s《%s》%d 学分，状态：开放\n", c.ID, c.Name, c.Credit)
189		case credit.ActionUpdated:
190			fmt.Fprintf(out, "课程 %s 尚未被要求引用，已更新为《%s》%d 学分（状态保持：%s）\n",
191				c.ID, c.Name, c.Credit, openText(c.Open))
192		default:
193			fmt.Fprintf(out, "课程 %s 已存在且内容一致，返回原记录（状态保持：%s）\n",
194				c.ID, openText(c.Open))
195		}
196		return exitOK, nil
197	}
198	
199	func cmdCourseToggle(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
200		if len(args) != 1 {
201			return exitRejected, fmt.Errorf("用法：%s <编号>", cmd)
202		}
203		open := cmd == "course-open"
204		c, err := s.SetCourseOpen(args[0], open)
205		if err != nil {
206			return exitRejected, err
207		}
208		fmt.Fprintf(out, "课程 %s《%s》状态：%s\n", c.ID, c.Name, openText(c.Open))
209		return exitOK, nil
210	}
211	
212	func cmdListCourses(s *credit.Store, out io.Writer) (int, error) {
213		courses := s.Courses()
214		if len(courses) == 0 {
215			fmt.Fprintln(out, "（尚无课程）")
216			return exitOK, nil
217		}
218		for _, c := range courses {
219			fmt.Fprintf(out, "课程 %s《%s》%d 学分，状态：%s\n", c.ID, c.Name, c.Credit, openText(c.Open))
220		}
221		return exitOK, nil
222	}
223	
224	func cmdReq(s *credit.Store, args []string, out io.Writer) (int, error) {
225		if len(args) != 3 {
226			return exitRejected, errors.New("用法：req <学生> <要求编号> <课程编号>")
227		}
228		r, action, err := s.AddRequirement(args[0], args[1], args[2])
229		if err != nil {
230			return exitRejected, err
231		}
232		if action == credit.ActionCreated {
233			fmt.Fprintf(out, "已为学生 %s 登记要求 %s，指向课程 %s\n", r.StudentID, r.ID, r.CourseID)
234		} else {
235			fmt.Fprintf(out, "学生 %s 的要求 %s 已存在且内容一致，返回原记录\n", r.StudentID, r.ID)
236		}
237		return exitOK, nil
238	}
239	
240	func cmdEnroll(s *credit.Store, args []string, out io.Writer) (int, error) {
241		if len(args) != 4 {
242			return exitRejected, errors.New("用法：enroll <学生> <要求编号> <学期> <修读编号>")
243		}
244		e, action, err := s.AddEnrollment(args[0], args[1], args[2], args[3])
245		if err != nil {
246			return exitRejected, err
247		}
248		if action == credit.ActionCreated {
249			fmt.Fprintf(out, "已登记修读 %s：学生 %s，要求 %s，学期 %s，状态：选课\n",
250				e.ID, e.StudentID, e.ReqID, e.Term)
251		} else {
252			fmt.Fprintf(out, "修读 %s 已存在且内容一致，返回原记录（状态：%s）\n",
253				e.ID, zhText(e.Result))
254		}
255		return exitOK, nil
256	}
257	
258	func cmdResult(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
259		if len(args) != 2 {
260			return exitRejected, fmt.Errorf("用法：%s <学生> <修读编号>", cmd)
261		}
262		result := credit.Passed
263		if cmd == "fail" {
264			result = credit.Failed
265		}
266		e, changed, err := s.SubmitResult(args[0], args[1], result)
267		if err != nil {
268			return exitRejected, err
269		}
270		if changed {
271			fmt.Fprintf(out, "修读 %s 结果已提交：%s\n", e.ID, zhText(e.Result))
272		} else {
273			fmt.Fprintf(out, "修读 %s 已提交过相同结果“%s”，返回原记录，不重复计学分\n",
274				e.ID, zhText(e.Result))
275		}
276		return exitOK, nil
277	}
278	
279	func cmdWaiver(s *credit.Store, args []string, out io.Writer) (int, error) {
280		if len(args) < 4 {
281			return exitRejected, errors.New("用法：waiver <学生> <要求编号> <免修编号> <依据...>")
282		}
283		student, reqID, waiverID := args[0], args[1], args[2]
284		basis := strings.Join(args[3:], " ")
285		w, action, err := s.ApplyWaiver(student, reqID, waiverID, basis)
286		if err != nil {
287			// 同编号换内容等冲突：不新增记录。
288			return exitRejected, err
289		}
290		if action == credit.ActionExisted {
291			fmt.Fprintf(out, "免修 %s 已提交过且内容一致，返回原申请，状态：%s\n",
292				w.ID, waiverText(w.Status))
293			return exitOK, nil
294		}
295		if w.Status == credit.WaiverApproved {
296			fmt.Fprintf(out, "免修 %s 有效：学生 %s 的要求 %s 凭依据 %q 满足，获得课程学分\n",
297				w.ID, w.StudentID, w.ReqID, w.Basis)
298			return exitOK, nil
299		}
300		// 被拒绝：申请内容与原因已记入该学生免修历史。
301		fmt.Fprintf(out, "免修申请 %s 已拒绝（已记入学生 %s 的免修历史）：%s\n",
302			w.ID, w.StudentID, w.Reason)
303		return exitRejected, nil
304	}
305	
306	func cmdRevoke(s *credit.Store, args []string, out io.Writer) (int, error) {
307		if len(args) < 2 {
308			return exitRejected, errors.New("用法：revoke-waiver <学生> <免修编号> [原因...]")
309		}
310		reason := strings.Join(args[2:], " ")
311		w, changed, err := s.RevokeWaiver(args[0], args[1], reason)
312		if err != nil {
313			return exitRejected, err
314		}
315		if changed {
316			fmt.Fprintf(out, "免修 %s 已撤销，原依据 %q 保留在免修历史；要求按修读情况重新判定\n",
317				w.ID, w.Basis)
318		} else {
319			fmt.Fprintf(out, "免修 %s 已是撤销状态，重复撤销不改变结果（原依据 %q 保留）\n",
320				w.ID, w.Basis)
321		}
322		return exitOK, nil
323	}
324	
325	func cmdCheck(s *credit.Store, args []string, out io.Writer) (int, error) {
326		if len(args) != 1 {
327			return exitRejected, errors.New("用法：check <学生>")
328		}
329		rep := s.CheckStudent(args[0])
330		if !rep.Found {
331			// 没有记录的学生：明确的不存在结果，且不写任何数据。
332			return exitRejected, fmt.Errorf("%s", rep.String())
333		}
334		if rep.Overflow {
335			// 该学生实际获得的总学分超出学分整数类型可表示范围：按业务规则
336			// 拒绝本次核对（退出码 1），只在标准错误点名学生与溢出事实。
337			// 不能向标准输出写任何正常核对报告，也不能给出截断、回绕或部分
338			// 累加的总学分。各门课程学分本身合法，所以这不是文件损坏（退出码
339			// 不是 2）；核对只读，不保存、不改动任何记录，show 仍可查看原件。
340			return exitRejected, fmt.Errorf("%s", rep.OverflowMessage())
341		}
342		fmt.Fprint(out, rep.String())
