7	
8	// 本文件从命令行入口回归“pass/fail 按用户给出的完整学生编号与修读编号
9	// 确定成绩归属”。记录文件可以合法保存带前后空白（普通空格、制表符、
10	// 全角空格）的编号，查询能把它们区分，提交结果也必须如此：
11	//   - 给 " s1 " 提交通过只命中本人的 e1，核对按本人要求获得学分并以
12	//     本人修读说明来源；"s1" 的状态、学分与来源保持原样；
13	//   - 同一学生名下 "e1" 与 " e1 " 分别处理，提交一份不影响另一份，
14	//     不误报重复提交或结果冲突；
15	//   - 完整编号找不到时按业务拒绝（退出码 1），明确报告学生不存在或
16	//     该学生名下不存在该修读，不输出提交成功的提示，不借用去空白后
17	//     能碰上的记录，也不补建修读，记录文件逐字节保持原样；
18	//   - 含前后空白的编号是合法记录，不能判为文件损坏（退出码 2）。
19	
20	// whitespaceCLIRecord 构造合法记录：学生 "s1" 与 " s1 " 各自的要求 r1
21	// 指向 4 学分课程 c1，名下各有一份尚未提交结果的修读 e1。
22	func whitespaceCLIRecord() *diskRecord {
23		return &diskRecord{
24			Version: 1,
25			Courses: []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
26			Students: []diskStudent{
27				{ID: "s1"},
28				{ID: " s1 "},
29			},
