14	// 另有通过修读也不能绕过。已拒绝申请的依据允许为空或只含空白；依据含
15	// 实际文字时其前后与中间的空白必须原样保留，读取不得修剪或改写。
16	//
17	// 这类矛盾无法经正常申请流程产生（空白依据的首次申请会被业务拒绝并记为
18	// rejected），因此损坏用例直接构造记录文件，聚焦 Load 读取历史这一路径。
19	
20	// blankBasisBase 构造结构完整、引用齐全的基础记录：学生 s1 的要求 r1
21	// 指向 4 学分课程 c1。withPass 时再附一条已通过修读 e1。
22	func blankBasisBase(withPass bool) *fileData {
23		d := &fileData{
24			Version:      recordVersion,
25			Courses:      []*Course{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
26			Students:     []*Student{{ID: "s1"}},
27			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
28		}
29		if withPass {
30			d.Enrollments = []*Enrollment{{
31				ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春",
32				Result: Passed, ResultSeq: 1,
33			}}
34			d.NextResultSeq = 1
35		}
36		return d
37	}
38	
39	// TestLoadRejectsApprovedWaiverWithBlankBasis 有效免修依据为空或全部为空白
40	// 字符时，无论空白由哪些字符、以什么方式混合组成，Load 都必须判为内容
41	// 损坏：错误点名记录文件、所属学生与免修编号，文件标记为已存在，原文件
42	// 逐字节保留，且不能返回可用于核对的 store。
43	func TestLoadRejectsApprovedWaiverWithBlankBasis(t *testing.T) {
44		blanks := map[string]string{
45			"空字符串":        "",
46			"普通空格":        "     ",
47			"制表符换行回车":     "\t\n\r\n\t",
48			"全角空格":        "　　　",
49			"不换行空格":       "     ",
50			"混合空白":        " \t　 \n  \r　",
51			"空白夹在前后无实际文字": "\n\t　  ",
52		}
53		for name, basis := range blanks {
54			t.Run(name, func(t *testing.T) {
55				d := blankBasisBase(false)
56				d.Waivers = []*Waiver{{
57					ID: "w1", StudentID: "s1", ReqID: "r1",
58					Basis: basis, Status: WaiverApproved,
59				}}
60				path, raw := writeRecord(t, d)
61	
62				s, existed, err := Load(path)
63				if err == nil {
64					t.Fatalf("有效免修依据为空白（%s）应判内容损坏拒绝读取，却得到 store=%v", name, s)
65				}
66				if !existed {
67					t.Fatalf("损坏文件应标记为已存在，existed=%v err=%v", existed, err)
68				}
69				msg := err.Error()
70				for _, want := range []string{path, "内容损坏", "s1", "w1", "有效免修", "依据"} {
71					if !strings.Contains(msg, want) {
72						t.Fatalf("错误信息应包含 %q（文件/学生/免修编号/缺少依据），得到：%v",
73							want, err)
74					}
75				}
76	
77				got, readErr := os.ReadFile(path)
78				if readErr != nil {
79					t.Fatal(readErr)
80				}
81				if string(got) != string(raw) {
82					t.Fatalf("拒绝读取不得改写原文件\nwant=%q\n got=%q", raw, got)
83				}
84			})
85		}
86	}
87	
88	// TestLoadBlankBasisApprovedNotMaskedByPassedEnrollment 即使该要求另有通过
89	// 修读（本来足以解释学分、满足要求），有效免修缺少依据仍然让整份记录
90	// 损坏：不能拿着通过记录继续核对学分、输出总学分或要求已满足。
91	func TestLoadBlankBasisApprovedNotMaskedByPassedEnrollment(t *testing.T) {
92		d := blankBasisBase(true)
93		d.Waivers = []*Waiver{{
94			ID: "w1", StudentID: "s1", ReqID: "r1",
95			Basis: " 　\t \n ", Status: WaiverApproved,
96		}}
97		path, raw := writeRecord(t, d)
98	
99		s, existed, err := Load(path)
100		if err == nil {
101			t.Fatalf("另有通过修读也不能放过缺少依据的有效免修，得到 store=%v", s)
102		}
103		if !existed {
104			t.Fatalf("应标记文件已存在，existed=%v err=%v", existed, err)
105		}
106		if msg := err.Error(); !strings.Contains(msg, "内容损坏") ||
107			!strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") {
108			t.Fatalf("错误应点名 s1 的有效免修 w1 缺少依据，得到：%v", err)
109		}
110		got, readErr := os.ReadFile(path)
111		if readErr != nil {
112			t.Fatal(readErr)
113		}
114		if string(got) != string(raw) {
115			t.Fatal("拒绝读取不得改写原文件")
116		}
117	}
118	
119	// TestLoadBlankBasisAttributesCorrectStudent 文件中另有完全合法的学生 s2
120	// （本人的课程、要求与一份依据齐全的有效免修）时，s1 名下缺少依据的有效
121	// 免修仍让整份文件不可读；错误必须归属 s1，不能误报 s2 的合法记录。
122	func TestLoadBlankBasisAttributesCorrectStudent(t *testing.T) {
123		d := blankBasisBase(false)
124		d.Courses = append(d.Courses, &Course{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
125		d.Students = append(d.Students, &Student{ID: "s2"})
126		d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c2"})
127		d.Waivers = []*Waiver{
128			{ID: "w1", StudentID: "s1", ReqID: "r1", Basis: "　", Status: WaiverApproved},
129			{ID: "w1", StudentID: "s2", ReqID: "r1", Basis: "s2 本人的依据", Status: WaiverApproved},
130		}
131		path, raw := writeRecord(t, d)
132	
133		s, _, err := Load(path)
134		if err == nil {
135			t.Fatalf("s1 名下有效免修缺少依据时必须整份拒绝，得到 store=%v", s)
136		}
137		msg := err.Error()
138		if !strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") {
139			t.Fatalf("错误应归属学生 s1 及其免修 w1，得到：%v", err)
140		}
141		if strings.Contains(msg, "学生 s2") {
142			t.Fatalf("s2 的免修依据齐全，不应被点名为问题记录，得到：%v", err)
143		}
144		got, readErr := os.ReadFile(path)
145		if readErr != nil {
146			t.Fatal(readErr)
147		}
148		if string(got) != string(raw) {
149			t.Fatal("拒绝读取不得改写原文件")
150		}
151	}
152	
153	// TestLoadRejectedWaiverBlankBasisStillLoads 已拒绝申请的依据允许为空或只
154	// 含空白（含全角空格、不换行空格）：记录正常读取，拒绝状态与原因照常
155	// 保留、核对中可查，但不获得学分；文件不因此判坏。
156	func TestLoadRejectedWaiverBlankBasisStillLoads(t *testing.T) {
157		d := blankBasisBase(true) // 有通过修读，r1 由通过记录满足
158		d.Waivers = []*Waiver{
159			{ID: "w0", StudentID: "s1", ReqID: "ghost", Basis: "",
160				Status: WaiverRejected, Reason: "目标要求 ghost 不存在或不属于该学生"},
161			{ID: "wr", StudentID: "s1", ReqID: "r1", Basis: " \t　 \n ",
162				Status: WaiverRejected, Reason: "免修依据为空"},
163		}
164		path, raw := writeRecord(t, d)
165	
166		s, existed, err := Load(path)
167		if err != nil || !existed {
168			t.Fatalf("已拒绝申请依据为空白不应判坏文件，existed=%v err=%v", existed, err)
169		}
170		rep := s.CheckStudent("s1")
171		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
172			t.Fatalf("r1 应由通过修读满足、计 4 学分，得到 学分=%d 未满足=%v",
173				rep.TotalCredits, rep.Unmet)
174		}
175		if st := rep.Requirements[0]; st.Source != "enrollment" || st.WaiverID != "" {
176			t.Fatalf("被拒绝的空白依据申请不能成为来源，得到 %+v", st)
177		}
178		if len(rep.RejectedWaivers) != 2 {
179			t.Fatalf("两条被拒绝历史都应保留，得到 %d 条", len(rep.RejectedWaivers))
180		}
181		for _, rj := range rep.RejectedWaivers {
182			if rj.Waiver.Status != WaiverRejected || rj.Reason == "" {
183				t.Fatalf("被拒绝记录应保留状态与原因，得到 %+v", rj)
184			}
185		}
186		// 只读核对不得改动文件。
187		if s.Dirty() {
188			t.Fatal("只读核对不应标记变更")
189		}
190		got, readErr := os.ReadFile(path)
191		if readErr != nil {
192			t.Fatal(readErr)
193		}
194		if string(got) != string(raw) {
195			t.Fatal("合法文件只读访问后内容必须保持不变")
196		}
197	}
198	
199	// TestLoadApprovedWaiverBasisWhitespacePreserved 依据含有实际文字时，前后
200	// 与中间的空白（缩进、换行、全角空格、不换行空格）都是材料的一部分：
201	// 记录必须正常读取，依据原文逐字符保留在免修历史中，核对以免修满足要求，
202	// 重新保存再加载后依据仍与原文件一致，读取/保存均不得修剪或改写。
203	func TestLoadApprovedWaiverBasisWhitespacePreserved(t *testing.T) {
204		basis := "\t\n  学科竞赛获奖证明　 \n  获奖证书编号：001  \n  "
205		d := blankBasisBase(false)
206		d.Waivers = []*Waiver{{
207			ID: "w1", StudentID: "s1", ReqID: "r1",
208			Basis: basis, Status: WaiverApproved,
209		}}
210		path, raw := writeRecord(t, d)
211	
212		s, existed, err := Load(path)
213		if err != nil || !existed {
214			t.Fatalf("含实际文字（带缩进与换行）的依据应正常读取，existed=%v err=%v",
215				existed, err)
216		}
217		w := s.Waiver("s1", "w1")
218		if w == nil || w.Status != WaiverApproved {
219			t.Fatalf("免修应保持有效，得到 %+v", w)
220		}
221		if w.Basis != basis {
222			t.Fatalf("依据中的前后/中间空白必须原样保留，\nwant=%q\n got=%q", basis, w.Basis)
223		}
224		rep := s.CheckStudent("s1")
225		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
226			t.Fatalf("r1 应由该有效免修满足、计 4 学分，得到 学分=%d 未满足=%v",
227				rep.TotalCredits, rep.Unmet)
228		}
229		if st := rep.Requirements[0]; st.Source != "waiver" || st.WaiverID != "w1" {
230			t.Fatalf("来源应是有效免修 w1，得到 %+v", st)
231		}
232	
233		// 重新保存后文件字节应与原文件一致（依据未被修剪），再次加载结论不变。
234		if err := s.Save(path); err != nil {
235			t.Fatalf("Save: %v", err)
236		}
237		saved, readErr := os.ReadFile(path)
238		if readErr != nil {
239			t.Fatal(readErr)
240		}
241		if string(saved) != string(raw) {
242			t.Fatalf("重新保存不得修剪或改写依据\nwant=%q\n got=%q", raw, saved)
243		}
244		reloaded, _, err := Load(path)
245		if err != nil {
246			t.Fatalf("重新保存后应可再次加载：%v", err)
247		}
248		if w2 := reloaded.Waiver("s1", "w1"); w2 == nil || w2.Basis != basis {
249			t.Fatalf("再次加载后依据原文应保持不变，得到 %+v", w2)
250		}
251	}
252	
253	// TestLoadRevokedWaiverBlankBasisStillRejected 已撤销免修的现有校验保持
254	// 不变：原依据全部为空白（含全角空格、不换行空格）同样判内容损坏。
255	func TestLoadRevokedWaiverBlankBasisStillRejected(t *testing.T) {
256		d := blankBasisBase(false)
257		d.Waivers = []*Waiver{{
258			ID: "wv", StudentID: "s1", ReqID: "r1",
259			Basis: " 　\t ", Status: WaiverRevoked, Reason: "材料无法核实",
260		}}
261		path, raw := writeRecord(t, d)
262		if _, _, err := Load(path); err == nil {
263			t.Fatal("已撤销免修原依据全为空白时仍应判内容损坏")
264		} else if msg := err.Error(); !strings.Contains(msg, "内容损坏") ||
265			!strings.Contains(msg, "s1") || !strings.Contains(msg, "wv") {
266			t.Fatalf("错误应点名 s1 的已撤销免修 wv，得到：%v", err)
267		}
268		got, readErr := os.ReadFile(path)
269		if readErr != nil {
270			t.Fatal(readErr)
271		}
272		if string(got) != string(raw) {
273			t.Fatal("拒绝读取不得改写原文件")
274		}
275	}
276	
277	// TestApplyWaiverBlankBasisBusinessRejectionUnchanged 首次正常提交空白依据
278	// 申请的行为保持不变：按业务规则拒绝（退出码语义在命令行层体现为 1），
279	// 申请内容与拒绝原因保留为 rejected 历史；保存后重新打开是合法记录，
280	// 拒绝历史可查且不获得学分——不会被新的读取校验反过来判成文件损坏。
281	func TestApplyWaiverBlankBasisBusinessRejectionUnchanged(t *testing.T) {
282		s := NewStore()
283		mustStudent(t, s, "s1")
284		mustCourse(t, s, "c1", "数学", 4)
285		mustReq(t, s, "s1", "r1", "c1")
286	
287		w, action, err := s.ApplyWaiver("s1", "r1", "w-empty", " \t　 \n  ")
288		if err != nil || action != ActionCreated {
289			t.Fatalf("空白依据首次申请不是硬错误，应新建一条被拒绝记录，得到 %+v action=%v err=%v",
290				w, action, err)
291		}
292		if w.Status != WaiverRejected || w.Reason != "免修依据为空" {
293			t.Fatalf("空白依据应按业务规则拒绝并保留原因，得到 %+v", w)
294		}
295	
296		dir := t.TempDir()
297		path := filepath.Join(dir, "records.json")
298		if err := s.Save(path); err != nil {
299			t.Fatalf("Save: %v", err)
300		}
301		reloaded, existed, err := Load(path)
302		if err != nil || !existed {
303			t.Fatalf("含被拒绝空白依据申请的文件应正常打开，existed=%v err=%v", existed, err)
304		}
305		w2 := reloaded.Waiver("s1", "w-empty")
306		if w2 == nil || w2.Status != WaiverRejected || w2.Reason != "免修依据为空" {
307			t.Fatalf("重新打开后被拒绝记录与原因应保留，得到 %+v", w2)
308		}
309		rep := reloaded.CheckStudent("s1")
310		if rep.TotalCredits != 0 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
311			t.Fatalf("被拒绝的空白依据申请不获得学分，得到 学分=%d 未满足=%v",
312				rep.TotalCredits, rep.Unmet)
313		}
314		if len(rep.RejectedWaivers) != 1 {
315			t.Fatalf("核对中应能查到这条被拒绝申请，得到 %d 条", len(rep.RejectedWaivers))
316		}
317	}
