36	// waiverConflictBase 构造一份结构完整、引用齐全的基础记录：
37	// 学生 s1 的要求 r1 指向 4 学分课程 c1。可选附一条已通过修读 e1。
38	func waiverConflictBase(withPass bool) *fileData {
39		d := &fileData{
40			Version: recordVersion,
41			Courses: []*Course{
42				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
43			},
44			Students:     []*Student{{ID: "s1"}},
45			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
