48			d.Enrollments = []*Enrollment{{
49				ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春",
50				Result: Passed, ResultSeq: 1,
51			}}
52			d.NextResultSeq = 1
53		}
54		return d
