57	// assertConflictRejected 是冲突用例的共同断言：Load 必须失败、文件标记为
58	// 已存在，错误点名问题文件、所属学生、目标要求与冲突的两个免修编号，
59	// 且原文件字节完整保留。
60	func assertConflictRejected(t *testing.T, path string, raw []byte, student, req, w1, w2 string) {
61		t.Helper()
62		s, existed, err := Load(path)
63		if err == nil {
64			t.Fatalf("同一学生同一要求存在两份有效免修时必须整份拒绝，却得到 store=%v", s)
65		}
66		if !existed {
67			t.Fatalf("冲突记录应标记为文件已存在，existed=%v err=%v", existed, err)
68		}
69		msg := err.Error()
70		for _, want := range []string{path, "内容损坏", student, req, w1, w2, "有效免修"} {
71			if !strings.Contains(msg, want) {
72				t.Fatalf("错误信息应包含 %q（文件/学生/要求/冲突免修编号），得到：%v", want, err)
73			}
74		}
75		got, readErr := os.ReadFile(path)
76		if readErr != nil {
77			t.Fatal(readErr)
78		}
79		if string(got) != string(raw) {
80			t.Fatalf("拒绝读取不得改写原文件\nwant=%q\n got=%q", raw, got)
81		}
82	}
