369		// s1：两项要求共 4+3=7 学分，来源分别是本人的 w1、w2，课程各不相同。
370		rep1 := s.CheckStudent("s1")
371		if rep1.TotalCredits != 7 || len(rep1.Unmet) != 0 {
372			t.Fatalf("s1 应得 7 学分且全部满足，得到学分=%d 未满足=%v", rep1.TotalCredits, rep1.Unmet)
373		}
374		if st := rep1.Requirements[0]; st.Req.ID != "r1" || st.Source != "waiver" ||
375			st.WaiverID != "w1" || st.Course.ID != "c1" || st.Course.Credit != 4 {
376			t.Fatalf("s1 的 r1 应由本人 w1 对应 4 学分课程满足，得到 %+v", st)
377		}
378		if st := rep1.Requirements[1]; st.Req.ID != "r2" || st.Source != "waiver" ||
379			st.WaiverID != "w2" || st.Course.ID != "c2" || st.Course.Credit != 3 {
380			t.Fatalf("s1 的 r2 应由本人 w2 对应 3 学分课程满足，得到 %+v", st)
381		}
382	
383		// s2：同号 r1/w1，但是本人的 3 学分课程与本人依据。
384		rep2 := s.CheckStudent("s2")
385		if rep2.TotalCredits != 3 || len(rep2.Unmet) != 0 {
386			t.Fatalf("s2 应得本人课程的 3 学分，得到学分=%d 未满足=%v", rep2.TotalCredits, rep2.Unmet)
387		}
388		if st := rep2.Requirements[0]; st.Source != "waiver" || st.WaiverID != "w1" ||
389			st.Course.ID != "c2" || st.Course.Credit != 3 {
390			t.Fatalf("s2 的 r1 应由本人 w1 对应本人 3 学分课程满足，得到 %+v", st)
391		}
392	
393		// 同号免修是两条独立记录，归属与依据各归各。
394		w1s1 := s.Waiver("s1", "w1")
395		w1s2 := s.Waiver("s2", "w1")
396		if w1s1 == nil || w1s2 == nil || w1s1 == w1s2 {
397			t.Fatalf("两名学生的同号免修应各自独立，得到 %p %p", w1s1, w1s2)
398		}
399		if w1s1.Basis != "s1-r1 依据" || w1s2.Basis != "s2-r1 依据" ||
400			w1s1.StudentID != "s1" || w1s2.StudentID != "s2" {
401			t.Fatalf("同号免修的依据应各归本人，得到 %+v %+v", w1s1, w1s2)
402		}
403	
404		// 合法记录上的只读核对不得改动文件。
405		_ = s.CheckStudent("s1")
406		_ = s.CheckStudent("s2")
407		_ = s.Waivers("s1")
408		_ = s.Waivers("s2")
409		if s.Dirty() {
410			t.Fatal("只读查询不应把记录标记为已变更")
411		}
