66	// writeDiskRecord 把记录序列化到临时文件，返回路径与原始字节。
67	func writeDiskRecord(t *testing.T, d *diskRecord) (string, []byte) {
68		t.Helper()
69		raw, err := json.MarshalIndent(d, "", "  ")
70		if err != nil {
71			t.Fatalf("序列化记录失败：%v", err)
72		}
73		raw = append(raw, '\n')
74		file := filepath.Join(t.TempDir(), "records.json")
75		if err := os.WriteFile(file, raw, 0o600); err != nil {
76			t.Fatalf("写入记录文件失败：%v", err)
77		}
78		return file, raw
79	}
80	
81	// assertFileByteIdentical 断言记录文件与写入时的内容逐字节一致。
82	func assertFileByteIdentical(t *testing.T, file string, want []byte, label string) {
83		t.Helper()
84		got, err := os.ReadFile(file)
85		if err != nil {
86			t.Fatalf("读取记录文件失败：%v", err)
87		}
88		if string(got) != string(want) {
89			t.Fatalf("%s不得改写原文件\nwant=%q\n got=%q", label, want, got)
90		}
91	}
92	
93	// assertConflictAccessRejected 用指定命令访问冲突文件：必须退出码 2、
94	// stdout 没有任何业务内容，stderr 点名文件、学生、要求与两个免修编号。
95	func assertConflictAccessRejected(t *testing.T, file string, raw []byte,
96		args []string, student, req, w1, w2 string, label string) {
97		t.Helper()
98		out, errText, code := runCLI(t, file, args...)
99		if code != exitFile {
100			t.Fatalf("%s：访问含两份有效免修的记录应退出码 %d，code=%d out=%q err=%q",
101				label, exitFile, code, out, errText)
102		}
103		if out != "" {
104			t.Fatalf("%s：拒绝整份记录时不应输出任何业务结果，out=%q", label, out)
105		}
106		for _, want := range []string{file, "内容损坏", student, req, w1, w2} {
107			if !strings.Contains(errText, want) {
108				t.Fatalf("%s：错误输出应点名文件/学生 %s/要求 %s/免修 %s、%s（缺 %q），err=%q",
109					label, student, req, w1, w2, want, errText)
110			}
111		}
112		if !strings.Contains(errText, "有效免修 "+w1) ||
113			!strings.Contains(errText, w2) {
114			t.Fatalf("%s：错误应说明同一要求存在两份有效免修 %s 与 %s，err=%q",
115				label, w1, w2, errText)
116		}
117		assertFileByteIdentical(t, file, raw, label+"：")
118	}
119	
120	// conflictRecord 构造结构完整、引用齐全的记录：s1 的 r1 指向 4 学分课程 c1，
121	// 同一要求下有两份编号不同、依据非空的有效免修。withPass 时再附一条已通过
122	// 修读，用于证明通过记录不能掩盖冲突。
123	func conflictRecord(withPass bool) *diskRecord {
124		d := &diskRecord{
125			Version: 1,
126			Courses: []diskCourse{
127				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
128			},
129			Students:     []diskStudent{{ID: "s1"}},
130			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
131			Waivers: []diskWaiver{
132				{ID: "w1", Student: "s1", Req: "r1", Basis: "学科竞赛获奖", Status: "approved"},
133				{ID: "w2", Student: "s1", Req: "r1", Basis: "外校同层次课程", Status: "approved"},
134			},
135		}
136		if withPass {
137			d.Enrollments = []diskEnr{{
138				ID: "e1", Student: "s1", Req: "r1", Term: "2024春",
139				Result: "passed", ResultSeq: 1,
140			}}
141			d.NextResultSeq = 1
142		}
143		return d
144	}
145	
146	// TestCLIDuplicateApprovedWaiversInFileRejectsAllCommands 文件完整可解析，
147	// 但 s1 的 r1 下有两份有效免修 w1、w2：check、show、列出课程乃至写入类命令
148	// 都必须退出码 2，不输出核对结果或登记成功信息，错误点名四要素且文件保留。
149	func TestCLIDuplicateApprovedWaiversInFileRejectsAllCommands(t *testing.T) {
150		file, raw := writeDiskRecord(t, conflictRecord(false))
151	
152		// 只读核对：不能挑其中一份免修继续核对，也不能出现总学分。
153		assertConflictAccessRejected(t, file, raw,
154			[]string{"check", "s1"}, "s1", "r1", "w1", "w2", "check 当事学生")
155	
156		// 历史查看同样拒绝：不能展示任何一份看似正常的免修。
157		assertConflictAccessRejected(t, file, raw,
158			[]string{"show", "s1"}, "s1", "r1", "w1", "w2", "show 当事学生")
159	
160		// 与冲突无关的只读命令也要在加载阶段整份拒绝。
161		assertConflictAccessRejected(t, file, raw,
162			[]string{"list-courses"}, "s1", "r1", "w1", "w2", "list-courses")
163	
164		// 写入类命令：不能报告登记成功，更不能把冲突文件覆盖成“干净”的新记录。
165		assertConflictAccessRejected(t, file, raw,
166			[]string{"student", "s9"}, "s1", "r1", "w1", "w2", "写入类命令 student")
167	
168		// 针对另一名尚未出现在文件里的学生核对：文件整体不可读，仍退出码 2。
169		assertConflictAccessRejected(t, file, raw,
170			[]string{"check", "ghost"}, "s1", "r1", "w1", "w2", "check 其他学生")
171	
172		assertFileByteIdentical(t, file, raw, "全部访问后：")
173	}
