265			t.Fatalf("合法免修应有效，得到 %+v action=%v err=%v", w, a, err)
266		}
267		// 该要求已有有效免修：再次申请被拒绝并入历史。
268		w, _, err = s.ApplyWaiver("s1", "r1", "w2", "另一依据")
269		if err != nil || w.Status != WaiverRejected {
270			t.Fatalf("已有有效免修时应拒绝新申请，得到 %+v err=%v", w, err)
