272		// 相同编号相同内容重复提交：返回原申请及其结果。
273		if w2, a, err := s.ApplyWaiver("s1", "r1", "w2", "另一依据"); err != nil ||
274			a != ActionExisted || w2.Status != WaiverRejected {
275			t.Fatalf("重复提交应返回原拒绝结果，得到 %+v action=%v err=%v", w2, a, err)
276		}
277		// 相同编号换内容：拒绝且原记录不变。
