287		s := NewStore()
288		mustStudent(t, s, "s1")
289		mustCourse(t, s, "c1", "数学", 4)
290	
291		// 目标要求尚不存在：首次申请被拒绝，编号、目标、依据与原因都保留。
292		w, a, err := s.ApplyWaiver("s1", "r1", "w1", "学科竞赛获奖")
293		if err != nil || a != ActionCreated || w.Status != WaiverRejected {
294			t.Fatalf("目标要求不存在应拒绝并保留申请，得到 %+v action=%v err=%v", w, a, err)
295		}
296		origReason := w.Reason
297		if origReason == "" {
298			t.Fatal("拒绝原因应非空")
299		}
300	
301		// 后来补建同编号要求。
302		mustReq(t, s, "s1", "r1", "c1")
303	
304		// 用原编号、原要求、原依据再次提交：返回最初的已拒绝申请，不新增、不改写。
305		for i := 0; i < 2; i++ {
306			w2, a, err := s.ApplyWaiver("s1", "r1", "w1", "学科竞赛获奖")
307			if err != nil || a != ActionExisted {
308				t.Fatalf("第 %d 次重复提交应幂等返回原申请，得到 action=%v err=%v", i+1, a, err)
309			}
310			if w2.Status != WaiverRejected || w2.ReqID != "r1" || w2.Basis != "学科竞赛获奖" ||
311				w2.Reason != origReason {
312				t.Fatalf("目标补建后重复提交不应改变原拒绝结果，得到 %+v", w2)
313			}
314		}
315		if n := len(s.Waivers("s1")); n != 1 {
316			t.Fatalf("重复提交不应新增申请，免修历史应有 1 条，得到 %d", n)
317		}
318	
319		// 核对：没有通过修读也没有有效免修，要求仍未满足，总学分为零，
320		// 被拒绝的旧申请不能成为学分来源。
321		rep := s.CheckStudent("s1")
322		if rep.TotalCredits != 0 {
323			t.Fatalf("被拒绝的申请不应产生学分，总学分=%d", rep.TotalCredits)
324		}
325		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
326			t.Fatalf("要求 r1 应仍列为未满足，得到 %v", rep.Unmet)
327		}
328		if len(rep.RejectedWaivers) != 1 {
329			t.Fatalf("核对应列出 1 条被拒绝的免修，得到 %d", len(rep.RejectedWaivers))
330		}
331		rj := rep.RejectedWaivers[0]
332		if rj.Waiver.ID != "w1" || rj.Waiver.ReqID != "r1" || rj.Waiver.Basis != "学科竞赛获奖" ||
333			rj.Reason != origReason {
334			t.Fatalf("核对中的被拒绝记录应保持原编号、要求、依据与原因，得到 %+v", rj)
335		}
336	
337		// 同编号换要求或换依据：按内容冲突拒绝，原申请与原核对结果不变。
338		mustCourse(t, s, "c2", "物理", 3)
339		mustReq(t, s, "s1", "r2", "c2")
340		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "学科竞赛获奖"); err == nil {
341			t.Fatal("已拒绝申请同编号换要求应被拒绝")
342		}
343		if _, _, err := s.ApplyWaiver("s1", "r1", "w1", "另一份依据"); err == nil {
344			t.Fatal("已拒绝申请同编号换依据应被拒绝")
345		}
346		if got := s.Waiver("s1", "w1"); got.Status != WaiverRejected ||
347			got.ReqID != "r1" || got.Basis != "学科竞赛获奖" || got.Reason != origReason {
348			t.Fatalf("内容冲突不应改动原申请，得到 %+v", got)
349		}
350		if rep := s.CheckStudent("s1"); rep.TotalCredits != 0 || len(rep.RejectedWaivers) != 1 {
351			t.Fatalf("内容冲突不应改变原核对结果，得到学分=%d 被拒绝=%d",
352				rep.TotalCredits, len(rep.RejectedWaivers))
353		}
354	
355		// 目标补建后，用新编号正常申请免修的既有行为不变。
356		w3, a, err := s.ApplyWaiver("s1", "r1", "w2", "外校同层次课程")
357		if err != nil || a != ActionCreated || w3.Status != WaiverApproved {
358			t.Fatalf("补建要求后新编号申请应正常生效，得到 %+v action=%v err=%v", w3, a, err)
359		}
360		rep = s.CheckStudent("s1")
361		if rep.TotalCredits != 4 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r2" {
362			t.Fatalf("新免修应正常计学分，得到学分=%d 未满足=%v", rep.TotalCredits, rep.Unmet)
363		}
364		if len(rep.RejectedWaivers) != 1 || rep.RejectedWaivers[0].Waiver.ID != "w1" {
365			t.Fatalf("旧拒绝记录应继续保留，得到 %+v", rep.RejectedWaivers)
366		}
367	}
