431		s := NewStore()
432		mustStudent(t, s, "s1")
433		mustCourse(t, s, "c1", "数学", 4)
434		mustReq(t, s, "s1", "r1", "c1")
435	
436		// 撤销不存在的免修应拒绝。
437		if _, _, err := s.RevokeWaiver("s1", "ghost", ""); err == nil {
438			t.Fatal("撤销不存在的免修应报错")
439		}
440	
441		// 无通过记录时申请并撤销：要求重新列为未满足，依据保留。
442		if _, _, err := s.ApplyWaiver("s1", "r1", "w1", "证明材料"); err != nil {
443			t.Fatal(err)
444		}
445		w, changed, err := s.RevokeWaiver("s1", "w1", "材料不实")
446		if err != nil || !changed || w.Status != WaiverRevoked || w.Basis != "证明材料" ||
447			w.Reason != "材料不实" {
448			t.Fatalf("撤销应保留依据与状态，changed=%v 得到 %+v err=%v", changed, w, err)
449		}
450		rep := s.CheckStudent("s1")
451		if rep.TotalCredits != 0 || len(rep.Unmet) != 1 {
452			t.Fatalf("撤销且无通过记录时应重新未满足，得到学分=%d 未满足=%v",
453				rep.TotalCredits, rep.Unmet)
454		}
455		// 重复撤销不改变结果。
456		if w2, changed, err := s.RevokeWaiver("s1", "w1", "again"); err != nil ||
457			changed || w2.Reason != "材料不实" {
458			t.Fatalf("重复撤销不应改变结果，changed=%v 得到 %+v err=%v", changed, w2, err)
459		}
460		// 已撤销的申请不能因重试重新生效。
