44	
45	// TestRevokeWaiverWhitespaceStudentIDExact 两名学生 "s1" 与 " s1 " 各有
46	// 一份有效免修 w1：撤销 " s1 " 的 w1 只命中本人的申请，本人的要求重新
47	// 未满足、失去学分、免修历史保留原要求与依据并记录撤销状态与原因；
48	// "s1" 的免修状态、学分和来源保持原样。
49	func TestRevokeWaiverWhitespaceStudentIDExact(t *testing.T) {
50		s, _ := mustLoadWhitespace(t, revokeWhitespaceTwoStudents())
51	
52		w, changed, err := s.RevokeWaiver(" s1 ", "w1", "材料无法核实")
53		if err != nil || !changed {
54			t.Fatalf("撤销 \" s1 \" 的 w1 应成功，changed=%v err=%v", changed, err)
55		}
56		if w.StudentID != " s1 " || w.ID != "w1" {
57			t.Fatalf("命中的应是 \" s1 \" 本人的 w1，得到 %+v", w)
58		}
59		if w.Status != WaiverRevoked || w.ReqID != "r1" ||
60			w.Basis != " s1 的获奖证明" || w.Reason != "材料无法核实" {
61			t.Fatalf("免修历史应保留原要求、原依据并记录撤销状态与原因，得到 %+v", w)
62		}
63	
64		// " s1 " 本人：没有通过修读，要求重新未满足、失去这份免修的 4 学分。
65		rep := s.CheckStudent(" s1 ")
66		if !rep.Found || rep.TotalCredits != 0 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
67			t.Fatalf("\" s1 \" 撤销后应回到 0 学分且 r1 未满足，得到 %+v", rep)
68		}
69		if st := rep.Requirements[0]; st.Satisfied || st.Source != "" || st.WaiverID != "" {
70			t.Fatalf("\" s1 \" 的 r1 不应再有免修来源，得到 %+v", st)
71		}
72		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w1" {
73			t.Fatalf("核对应列出 \" s1 \" 的已撤销免修 w1，得到 %v", rep.RevokedWaivers)
74		}
75	
76		// "s1" 保持原样：w1 仍有效、r1 满足、4 学分且来源是本人的有效免修。
77		if got := s.Waiver("s1", "w1"); got == nil || got.Status != WaiverApproved ||
78			got.Basis != "s1的获奖证明" {
79			t.Fatalf("\"s1\" 的 w1 不应被改写，得到 %+v", got)
80		}
81		rep = s.CheckStudent("s1")
82		if !rep.Found || rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
83			t.Fatalf("\"s1\" 应仍为 4 学分且 r1 已满足，得到 %+v", rep)
84		}
85		if st := rep.Requirements[0]; !st.Satisfied || st.Source != "waiver" || st.WaiverID != "w1" {
86			t.Fatalf("\"s1\" 的来源应仍是本人有效免修 w1，得到 %+v", st)
87		}
88		if len(rep.RevokedWaivers) != 0 {
89			t.Fatalf("\"s1\" 不应出现已撤销免修，得到 %v", rep.RevokedWaivers)
90		}
91	}
92	
93	// TestRevokeWaiverWhitespaceWaiverIDExact 同一学生名下 "w1" 与 " w1 " 是
94	// 指向不同要求的两份有效免修：撤销 " w1 " 只处理带空格的那份（其要求
95	// 重新未满足、失去相应学分），"w1" 继续有效，另一份要求的满足情况、
96	// 学分与来源不受影响。
97	func TestRevokeWaiverWhitespaceWaiverIDExact(t *testing.T) {
98		d := &fileData{
99			Version: recordVersion,
100			Courses: []*Course{
101				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
102				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
103			},
104			Students: []*Student{{ID: "s1"}},
105			Requirements: []*Requirement{
106				{ID: "r1", StudentID: "s1", CourseID: "c1"},
107				{ID: "r2", StudentID: "s1", CourseID: "c2"},
108			},
109			Waivers: []*Waiver{
110				{ID: "w1", StudentID: "s1", ReqID: "r1", Basis: "竞赛获奖", Status: WaiverApproved},
111				{ID: " w1 ", StudentID: "s1", ReqID: "r2", Basis: "外校修读证明", Status: WaiverApproved},
112			},
113		}
114		s, _ := mustLoadWhitespace(t, d)
115	
116		w, changed, err := s.RevokeWaiver("s1", " w1 ", "材料无法核实")
117		if err != nil || !changed {
118			t.Fatalf("撤销 \" w1 \" 应作为独立免修被命中，changed=%v err=%v", changed, err)
119		}
120		if w.ID != " w1 " || w.StudentID != "s1" || w.ReqID != "r2" ||
121			w.Basis != "外校修读证明" || w.Status != WaiverRevoked || w.Reason != "材料无法核实" {
122			t.Fatalf("命中的应是 \" w1 \" 本身且原要求、原依据保留，得到 %+v", w)
123		}
124	
125		// r2 失去免修重新未满足，总学分只剩 r1 的 4 学分，来源仍是 w1。
126		rep := s.CheckStudent("s1")
127		if rep.TotalCredits != 4 {
128			t.Fatalf("撤销 \" w1 \" 后应只剩 r1 的 4 学分，得到 %d", rep.TotalCredits)
129		}
130		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r2" {
131			t.Fatalf("应只有 r2 重新未满足，得到 %v", rep.Unmet)
132		}
133		statuses := map[string]RequirementStatus{}
134		for _, st := range rep.Requirements {
135			statuses[st.Req.ID] = st
136		}
137		if st := statuses["r1"]; !st.Satisfied || st.Source != "waiver" || st.WaiverID != "w1" {
138			t.Fatalf("r1 应继续由有效免修 w1 满足，得到 %+v", st)
139		}
140		if st := statuses["r2"]; st.Satisfied || st.Source != "" {
141			t.Fatalf("r2 应重新未满足，得到 %+v", st)
142		}
143		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != " w1 " {
144			t.Fatalf("已撤销列表应只含 \" w1 \"，得到 %v", rep.RevokedWaivers)
145		}
146	
147		// 不带空格的 w1 继续有效。
148		if got := s.Waiver("s1", "w1"); got == nil || got.Status != WaiverApproved {
149			t.Fatalf("\"w1\" 应继续有效，得到 %+v", got)
150		}
151	}
152	
153	// TestRevokeWaiverWhitespaceNoBorrow 完整编号找不到时必须明确拒绝：
154	// 即使去掉空白后能碰上另一名学生或另一份免修，也绝不借用那份记录，
155	// 不改写编号、不合并申请、不新增免修历史。普通空格、制表符、全角空格
156	// 一样不能被忽略。
157	func TestRevokeWaiverWhitespaceNoBorrow(t *testing.T) {
158		// 学生编号带各种前后空白且与既有编号都不完全一致：应报学生不存在，
159		// 两名学生的 w1 都必须保持有效，且不产生任何变更。
160		for _, student := range []string{" s1", "s1  ", "s1 ", "\ts1", "　s1"} {
161			// s0 含 "s1" 与 " s1 "：这些输入都不等于其中任何一个。
162			s, _ := mustLoadWhitespace(t, revokeWhitespaceTwoStudents())
163			_, _, err := s.RevokeWaiver(student, "w1", "原因")
164			if err == nil || !strings.Contains(err.Error(), "不存在") || !strings.Contains(err.Error(), "学生") {
165				t.Fatalf("学生 %q 不存在，撤销应明确报学生不存在，得到 %v", student, err)
166			}
167			for _, sid := range []string{"s1", " s1 "} {
168				if got := s.Waiver(sid, "w1"); got == nil || got.Status != WaiverApproved {
169					t.Fatalf("学生 %q 被拒绝后 %s 的 w1 不应变化，得到 %+v", student, sid, got)
170				}
171			}
172			if s.Dirty() {
173				t.Fatalf("被拒绝的撤销不应产生变更（学生 %q）", student)
174			}
175		}
176	
177		// 学生存在但免修编号带各种前后空白：应报该学生名下不存在该免修，
178		// 既有的 w1 保持有效，不产生变更。
179		for _, waiverID := range []string{" w1", "w1  ", "w1 ", "\tw1", "　w1"} {
180			s, _ := mustLoadWhitespace(t, revokeWhitespaceTwoStudents())
181			_, _, err := s.RevokeWaiver("s1", waiverID, "原因")
182			if err == nil || !strings.Contains(err.Error(), "不存在") {
183				t.Fatalf("免修 %q 不存在于 s1 名下，撤销应明确拒绝，得到 %v", waiverID, err)
184			}
185			if !strings.Contains(err.Error(), "s1") {
186				t.Fatalf("错误应点名学生 s1 名下不存在该免修，得到 %v", err)
187			}
188			if got := s.Waiver("s1", "w1"); got == nil || got.Status != WaiverApproved {
189				t.Fatalf("免修 %q 被拒绝后 s1 的 w1 不应变化，得到 %+v", waiverID, got)
190			}
191			if n := len(s.Waivers("s1")); n != 1 {
192				t.Fatalf("被拒绝的撤销不应新增免修历史，s1 应有 1 条，得到 %d", n)
193			}
194			if s.Dirty() {
195				t.Fatalf("被拒绝的撤销不应产生变更（免修 %q）", waiverID)
196			}
197		}
198	}
199	
200	// TestRevokeWaiverWhitespaceRejectedStillRejected 完整编号命中的若是一份
201	// 已拒绝申请，仍不能撤销，也不能借用另一名学生同号的有效免修；另一名
202	// 学生的有效免修保持原样。
203	func TestRevokeWaiverWhitespaceRejectedStillRejected(t *testing.T) {
204		d := &fileData{
205			Version: recordVersion,
206			Courses: []*Course{
207				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
208			},
209			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
210			Requirements: []*Requirement{
211				{ID: "r1", StudentID: "s1", CourseID: "c1"},
212			},
213			Waivers: []*Waiver{
214				// s1 的 w1 有效。
215				{ID: "w1", StudentID: "s1", ReqID: "r1", Basis: "竞赛获奖", Status: WaiverApproved},
216				// " s1 " 的 w1 是当时目标要求不存在而被拒绝的申请。
217				{ID: "w1", StudentID: " s1 ", ReqID: "rX", Basis: "材料",
218					Status: WaiverRejected, Reason: "目标要求 rX 不存在或不属于该学生"},
219			},
220		}
221		s, _ := mustLoadWhitespace(t, d)
222	
223		_, _, err := s.RevokeWaiver(" s1 ", "w1", "撤销原因")
224		if err == nil || !strings.Contains(err.Error(), "已被拒绝") {
225			t.Fatalf("撤销 \" s1 \" 名下已拒绝的 w1 应被拒绝，得到 %v", err)
226		}
227		// 命中的是本人的拒绝记录：拒绝原因保留，状态不变。
228		if got := s.Waiver(" s1 ", "w1"); got == nil || got.Status != WaiverRejected {
229			t.Fatalf("\" s1 \" 的已拒绝 w1 应保持原样，得到 %+v", got)
230		}
231		// 不能借用 s1 的同号有效免修：s1 的 w1 仍有效、学分不变。
232		if got := s.Waiver("s1", "w1"); got == nil || got.Status != WaiverApproved {
233			t.Fatalf("s1 的有效 w1 不应受影响，得到 %+v", got)
234		}
235		if rep := s.CheckStudent("s1"); rep.TotalCredits != 4 {
236			t.Fatalf("s1 应仍获得 4 学分，得到 %d", rep.TotalCredits)
237		}
238		if s.Dirty() {
239			t.Fatal("被拒绝的撤销不应产生变更")
240		}
241	}
242	
243	// TestRevokeWaiverWhitespaceRulesAfterExactHit 准确命中带空白的编号后
244	// 沿用现有规则：有通过记录时撤销后仍只计一份课程学分、来源恢复为最先
245	// 提交的通过记录；重复撤销返回原结果且后来的原因不覆盖首次撤销原因。
246	func TestRevokeWaiverWhitespaceRulesAfterExactHit(t *testing.T) {
247		d := &fileData{
248			Version: recordVersion,
249			Courses: []*Course{
250				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
251			},
252			Students: []*Student{{ID: " s1 "}},
253			Requirements: []*Requirement{
254				{ID: "r1", StudentID: " s1 ", CourseID: "c1"},
255			},
256			Enrollments: []*Enrollment{
257				{ID: "e2", StudentID: " s1 ", ReqID: "r1", Term: "2024春", Result: Passed, ResultSeq: 1},
258				{ID: "e1", StudentID: " s1 ", ReqID: "r1", Term: "2024秋", Result: Passed, ResultSeq: 2},
259			},
260			Waivers: []*Waiver{
261				{ID: "w1", StudentID: " s1 ", ReqID: "r1", Basis: "竞赛获奖", Status: WaiverApproved},
262			},
263			NextResultSeq: 2,
264		}
265		s, _ := mustLoadWhitespace(t, d)
266	
267		w, changed, err := s.RevokeWaiver(" s1 ", "w1", "首次撤销：材料存疑")
268		if err != nil || !changed {
269			t.Fatalf("首次撤销应成功，changed=%v err=%v", changed, err)
270		}
271		// 有通过记录：继续满足、只计一份 4 学分，来源恢复为最先提交的 e2。
272		rep := s.CheckStudent(" s1 ")
273		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
274			t.Fatalf("撤销后有通过记录应继续满足、仍为 4 学分，得到 %+v", rep)
275		}
276		st := rep.Requirements[0]
277		if st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
278			t.Fatalf("撤销后来源应恢复为最先提交通过的 e2，得到 %+v", st)
279		}
280		if len(st.PassedEnrollmentIDs) != 2 {
281			t.Fatalf("修读历史应保留两份通过记录，得到 %v", st.PassedEnrollmentIDs)
282		}
283	
284		// 重复撤销：返回原结果，后来给出的原因不覆盖首次撤销原因，不再产生变更。
285		again, changed, err := s.RevokeWaiver(" s1 ", "w1", "后来给出的另一原因")
286		if err != nil || changed || again != w {
287			t.Fatalf("重复撤销应幂等返回原记录，changed=%v err=%v again=%+v", changed, err, again)
288		}
289		if w.Reason != "首次撤销：材料存疑" || w.Status != WaiverRevoked {
290			t.Fatalf("首次撤销原因不应被覆盖，得到 %+v", w)
291		}
292		if n := len(s.Waivers(" s1 ")); n != 1 {
293			t.Fatalf("重复撤销不应新增免修历史，得到 %d 条", n)
294		}
295	}
